args.command:
ls -la /output && for args in "--a hello --b 5" "--a  --b 0" "--a it's --b -3" "--a=hi --b=42" "--a x --b +7"; do
  diff <(/workspace/dataset/test11_executable $args 2>&1; echo "exit:$?") <(node /output/test11.mjs $args 2>&1; echo "exit:$?") > /dev/null && echo "OK: [$args]" || { echo "MISMATCH: [$args]"; diff <(/workspace/dataset/test11_executable $args 2>&1) <(node /output/test11.mjs $args 2>&1); }
done

for v in $'a\nb' 'back\slash' 'say "hi"' $'mix\'ed"q' 'héllo→世界' '  spaces  '; do
  diff <(/workspace/dataset/test11_executable --a "$v" --b 9) <(node /output/test11.mjs --a "$v" --b 9) > /dev/null && echo "OK" || { echo "MISMATCH for [$v]"; diff <(/workspace/dataset/test11_executable --a "$v" --b 9) <(node /output/test11.mjs --a "$v" --b 9); }
done
